
/* 仮の見た目（配置と読みやすさだけ）。色・字・アイコンの最終判断はデックと本人。 */
:root{
  --bg:#f5f2ea; --panel:#fffdf8; --ink:#14262a; --mute:#5b6a6c; --line:#ddd6c6;
  --accent:#1d4a4c; --accent-ink:#ffffff; --gold:#c6a874; --warn:#8a4a17; --bad:#a23a32; --soft:#e8eeea;
  --r:14px; --pad:16px;
  font-family:-apple-system,BlinkMacSystemFont,"Helvetica Neue","Hiragino Sans",sans-serif;
}
@media (prefers-color-scheme:dark){:root{--bg:#112025;--panel:#17292e;--ink:#f3eee2;--mute:#a9b7b4;--line:#2a4046;--accent:#d9bc78;--accent-ink:#112025;--gold:#d9bc78;--warn:#e0a368;--bad:#ef8a80;--soft:#1e3a3d}}
*{box-sizing:border-box}
html,body{margin:0;background:var(--bg);color:var(--ink)}
body{padding-bottom:calc(76px + env(safe-area-inset-bottom,0px));min-height:100vh;font-size:16px;line-height:1.5}
main{max-width:560px;margin:0 auto;padding:calc(14px + env(safe-area-inset-top,0px)) var(--pad) 24px;display:flex;flex-direction:column;gap:14px}
h1{font-size:15px;font-weight:600;color:var(--mute);margin:0;letter-spacing:.02em}
h2{font-size:18px;margin:0 0 6px}
p{margin:0}
.card{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:var(--pad)}
.big{font-size:56px;line-height:1.05;font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums;margin:2px 0}
.sub{color:var(--mute);font-size:14px}
.row{display:flex;gap:10px;align-items:center;justify-content:space-between}
.row>*{min-width:0}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
label{display:block;font-size:13px;color:var(--mute);margin-bottom:4px}
input,select{width:100%;font:inherit;color:var(--ink);background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:12px;min-height:46px}
input[type="date"]{display:block;min-width:0;max-width:100%;-webkit-appearance:none;appearance:none;text-align:left}
.card div,.card section,main>*{min-width:0}
input,select{max-width:100%}
input[type="date"]::-webkit-date-and-time-value{text-align:left;min-width:0}
button{font:inherit;min-height:46px;border-radius:12px;border:1px solid var(--line);background:var(--panel);color:var(--ink);padding:10px 14px;cursor:pointer}
button.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink);font-weight:600}
button.link{border:0;background:none;color:var(--accent);padding:6px 4px;min-height:36px;text-decoration:underline}
button.danger{color:var(--bad)}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chip{min-height:40px;border-radius:999px;padding:6px 14px}
.chip.on{background:var(--soft);border-color:var(--accent);color:var(--accent)}
.list{display:flex;flex-direction:column}
.item{display:flex;justify-content:space-between;gap:10px;padding:12px 0;border-bottom:1px solid var(--line)}
.item:last-child{border-bottom:0}
.item .l{min-width:0}.item .r{text-align:right;font-variant-numeric:tabular-nums;flex:0 1 auto;max-width:64%}.item .r button{white-space:nowrap;margin-left:8px}
.tag{display:inline-block;font-size:12px;padding:1px 8px;border-radius:999px;background:var(--soft);color:var(--accent)}
.tag.warn{background:#f6e6d6;color:var(--warn)}
.note{background:var(--soft);border-radius:var(--r);padding:12px 14px;font-size:14px}
.over{color:var(--bad)}
.tabs{position:fixed;left:0;right:0;bottom:0;display:flex;background:var(--panel);border-top:1px solid var(--line);padding:6px 6px calc(6px + env(safe-area-inset-bottom,0px))}
.tabs button{flex:1;border:0;background:none;min-height:52px;color:var(--mute);font-size:14px}
.tabs button.on{color:var(--accent);font-weight:700}
.demobar{position:sticky;top:0;z-index:5;background:var(--accent);color:var(--accent-ink);padding:10px 14px;font-size:14px;display:flex;justify-content:space-between;gap:10px;align-items:center}
.demobar a{color:inherit;font-weight:700}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
@media (prefers-reduced-motion:no-preference){button{transition:background .15s}}

/* 表紙の「金の割れ目」を、細い飾りとして少しだけ（2026-10-26）。意味を伝える文字には使わない */
.big{position:relative;padding-bottom:10px;margin-bottom:8px}
.big::after{content:"";position:absolute;left:0;bottom:0;width:72px;height:3px;border-radius:2px;background:var(--gold)}
.tabs button{border-radius:0;white-space:nowrap;padding-left:4px;padding-right:4px}
.tabs button.on{box-shadow:inset 0 3px 0 var(--gold)}
/* 開閉できる項目（なぜこの金額？／記録を忘れた？）。見た目の仕上げはデックの担当。ここは動きだけ。 */
details.why{margin-top:12px}
details.why>summary{cursor:pointer;font-weight:600;list-style:none;padding:2px 0}
details.why>summary::-webkit-details-marker{display:none}
details.why>summary::after{content:"▼";float:right;font-size:12px;color:var(--muted,#888)}
details.why[open]>summary::after{content:"▲"}

/* 凪（Yuji Boku・OFL・「凪」1文字だけ抜き出し）。今日の金額カードだけ */
.card.hero{position:relative;background:#14262a;color:#f5f2ea;border-color:#14262a;overflow:hidden}
.card.hero h1,.card.hero .sub{color:#e7e4d9}
.card.hero .big{color:#fffdf8}
.card.hero .big.over{color:#ffb4a0}
.card.hero button.link{color:#eed29b}
.card.hero .big::after{background:#c6a874}

/* 絵付きボタン入力と今月の記録（2026-10-28） */
h3.sec{font-size:16px;margin:16px 0 4px}
.pick{margin:10px 0 6px}
.ico{display:inline-flex;color:var(--accent);flex:none}
.catgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 12px}
.catbtn{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-height:84px;padding:10px 6px;border-radius:var(--r);font-weight:600;font-size:14px}
.catbtn.on{background:var(--soft);border-color:var(--accent);border-width:2px}
.usualgrid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}
.usualwrap{position:relative}
.usualbtn{display:flex;align-items:center;gap:10px;width:100%;min-height:64px;text-align:left;border-radius:var(--r);background:var(--soft)}
.usualbtn .tx{display:flex;flex-direction:column;min-width:0}
.usualbtn .nm{font-weight:700;font-size:14px}.usualbtn .am{font-size:14px;color:var(--mute);font-variant-numeric:tabular-nums}
.xbtn{position:absolute;top:-6px;right:-4px;min-height:28px;width:28px;padding:0;font-size:12px;text-decoration:none;background:var(--panel);border:1px solid var(--line);border-radius:999px}
.mrow{margin:12px 0}
.mhead{display:flex;align-items:center;gap:10px}
.mhead .nm{flex:1;font-weight:600}.mhead .pc{width:44px;text-align:right;color:var(--mute);font-size:14px}
.mbar{height:10px;border-radius:999px;background:var(--soft);margin-top:6px;overflow:hidden}
.mbar span{display:block;height:100%;border-radius:999px;background:var(--accent)}
button:disabled{opacity:.35;cursor:default}
.topnav button.link{font-size:28px;min-width:48px;text-decoration:none;line-height:1}

/* 全部のお金 */
.card.money .mrow{display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px solid var(--line);font-variant-numeric:tabular-nums}
.card.money .mrow b{font-weight:700}.card.money .mrow.sub2{padding:2px 0 2px 4px;font-size:14px;color:var(--mute);border-bottom:0}
.card.money .mrow.total{border-bottom:0;border-top:2px solid var(--line);margin-top:4px;padding-top:10px;font-size:18px}
.keeprow{display:flex;gap:8px;align-items:center;margin:8px 0}.keeprow input:first-child{flex:1.4;min-width:0}.keeprow input:nth-child(2){flex:1;min-width:0}

details.more{margin:10px 0}details.more summary{cursor:pointer;color:var(--accent,#1d4b52);font-weight:600;padding:6px 0}
.editbox{padding:10px 0;border-bottom:1px solid var(--line)}.editbox input,.editbox select{width:100%}

.tapnum{text-decoration:underline dotted;text-underline-offset:4px;cursor:pointer}.tapedit{display:inline-flex;gap:6px;align-items:center;flex-wrap:wrap}.tapedit input{width:9em;min-height:40px}.card.money .mrow.tap{cursor:pointer}
.card.hero .note{background:rgba(255,255,255,.1);color:#f5f2ea;border:1px solid rgba(255,255,255,.2)}
.card.money .mrow b{white-space:nowrap}
.tapnum{overflow-wrap:anywhere}.item .r{min-width:0}.item .r .tapnum{display:inline-block;max-width:100%}.keeprow input:nth-child(2){min-width:7.5em}.keeprow{flex-wrap:wrap}
.big{max-width:100%;overflow:hidden;white-space:nowrap}.keeprow input:first-child{flex:1 1 100%}.item .l{flex:1 1 auto;overflow-wrap:anywhere}.item .r{flex-shrink:1}.item .r button{margin-left:6px}.chip,.qa button,.favs button{overflow-wrap:anywhere;white-space:normal}
.usualbtn{overflow-wrap:anywhere;white-space:normal;min-width:0;max-width:100%}.usualwrap{min-width:0}
.tapnum{display:inline-block;padding:8px 2px;margin:-8px -2px}
::placeholder{color:#686868;opacity:1}
@media (prefers-color-scheme:dark){::placeholder{color:#9aa6a4}}
