summary{min-height:44px;box-sizing:border-box;padding-top:10px;padding-bottom:10px}
.chip{min-height:44px}
.item{flex-wrap:wrap}.item .l{flex:1 1 55%;min-width:0}.item .r{flex:0 1 auto;max-width:100%;min-width:0;margin-left:auto}
.backbtn{display:inline-flex;align-items:center;margin:0 0 6px;font-weight:600}
.tapnum{white-space:nowrap;overflow-wrap:normal}
.need{background:var(--soft)}.needbig{font-size:34px;font-weight:700;line-height:1.1;margin:2px 0 6px;font-variant-numeric:tabular-nums}.promise{margin:6px 0 12px;padding:12px 14px;border-radius:14px;background:var(--soft)}.promisebig{font-size:19px;font-weight:700;line-height:1.35;margin:0 0 6px}
.buycheck{border:2px solid var(--gold)}.verdict{font-size:18px;font-weight:600;line-height:1.4;padding:10px 12px;border-radius:12px;background:var(--soft);margin-top:6px}.verdict.good{background:#dcefe3;color:#14452b}.verdict.warn{background:#fbe7c8;color:#6a3d00}@media (prefers-color-scheme:dark){.verdict.good{background:#1d3d2b;color:#cfeedd}.verdict.warn{background:#4a3414;color:#fbe1b4}}.meter{height:10px;border-radius:6px;background:rgba(255,255,255,.18);margin:8px 0 4px;overflow:hidden}.meterfill{height:100%;background:var(--gold);border-radius:6px}.meterfill.over{background:#ef8a80}
.chipmine{display:inline-flex;align-items:center;gap:2px}.chipx{min-height:44px;min-width:44px;border-radius:999px;padding:0 10px;background:transparent;border-color:transparent;color:var(--muted,#777)}


