/* 朱印案：数字は無地の紙面に表示する。 */
html:root{color-scheme:light;--bg:#f3ecdf;--panel:#fffdf8;--ink:#20272a;--mute:#435157;--line:#a3907c;--accent:#85271e;--accent-ink:#fff;--gold:#926d37;--warn:#713d00;--bad:#8e211b;--soft:#f2e9db}
body{background:#eee7d9;color:#20272a}main{gap:16px}.card{background:#fffdf8;color:#20272a}.card.hero{isolation:isolate;overflow:hidden}.card.hero .big,.card.hero .big.over{display:block;width:fit-content;max-width:100%;background:#fffdf8;color:#78241d;border:3px solid #9b3025;padding:8px 12px;line-height:1.1;overflow-wrap:anywhere;word-break:break-word;font-variant-numeric:tabular-nums}.card.hero .big::after{display:none}.card.hero .note{background:#fffaf0;color:#19262a}.card.hero .note button.link,.card.hero .note a{color:#702118}.tabs button.on{color:#702118}.card.hero button.link{color:#fff0bb}

body{background:#e8dfcf}.card{border:3px solid #8e2a22;border-left:12px solid #20272a;border-radius:0;box-shadow:5px 5px 0 #d9bfa1}.card h2{border:3px double #9b3025;padding:3px 9px}.card.hero{background:#20272a;border:5px double #bd8d6a;border-left:14px solid #9b3025;padding:20px 16px}.card.hero .big,.card.hero .big.over{border:7px double #9b3025;box-shadow:inset 0 0 0 3px #f2e4d5,4px 4px 0 #9b3025}.tabs{border-top:7px solid #9b3025}.tabs button.on{box-shadow:inset 0 0 0 3px #9b3025}button.primary{box-shadow:inset 0 0 0 2px #e7c6a5}


/* 共通：色の固定・注意面・操作領域 */
html:root{color-scheme:light;--bg:#f1eee5;--panel:#fffefa;--ink:#20272a;--mute:#435157;--line:#a89a87;--accent:#81291f;--accent-ink:#fff;--gold:#896425;--warn:#713d00;--bad:#8e211b;--soft:#f1e8da}
html,body{background:var(--bg);color:var(--ink)}main{padding-left:14px;padding-right:14px;gap:16px}.card{background:var(--panel);color:var(--ink);padding:16px}.card.hero{isolation:isolate;overflow:hidden}.card.hero h1,.card.hero .sub{color:#fff4e6}.card.hero .big,.card.hero .big.over{display:block;width:fit-content;max-width:100%;background:#fffefa;color:#702118;border:2px solid #a47553;padding:8px 10px;line-height:1.1;font-size:clamp(32px,11vw,56px);overflow-wrap:anywhere;word-break:break-word}.card.hero .big::after{display:none}.card.hero button.link{color:#fff0bb}.card.hero .note{background:#fffaf0;color:#19262a}.card.hero .note button.link,.card.hero .note a{color:#702118}
button,button.link,.chip,.chipx,.xbtn{min-width:44px;min-height:44px}.xbtn{width:44px;height:44px}button.primary{background:#81291f;color:#fff}button.link{color:#702118}input,select{background:#fffefa;color:#20272a;border-color:#81715f}.note{color:#19262a;background:#f1e8da}.usualbtn{background:#f1e8da}.chip.on,.catbtn.on{color:#19262a;background:#f1e8da}#view>p:not(.card){background:#fffefa;color:#20272a;padding:12px}#view>button.link{background:#fffefa;color:#702118;padding:8px 12px}.tabs{background:#fffefa}.tabs button{flex:1 1 0;min-width:44px;min-height:52px;padding-left:1px;padding-right:1px;white-space:normal;line-height:1.15;color:#435157}.tabs button.on{color:#702118}.big{max-width:100%}details.why>summary::after,details.why[open]>summary::after{content:""}
@media(max-width:400px){.card .row:has(>button[style*="flex"])>button[style*="flex"]{flex:1 1 0!important;min-width:44px;min-height:44px;padding-left:2px;padding-right:2px;font-size:12px;letter-spacing:-.03em;white-space:nowrap}}@media(max-width:360px){.tabs button{font-size:12px;letter-spacing:-.01em}}


/* 絵は文字を置かない独立した先頭帯。 */
.card.hero{background:#17325b;color:#fff;overflow:hidden;padding:16px;border:3px solid #a78a60;border-radius:8px;isolation:isolate}
.card.hero::before{content:"";display:block;position:static;width:100%;height:auto;aspect-ratio:2 / 1;background-image:url("data:image/webp;base64,");background-size:cover;background-position:center;border-radius:4px;margin:0 0 14px;pointer-events:none}
.card.hero h1,.card.hero .sub{color:#fff6e9}.card.hero .big,.card.hero .big.over{background:#fffefa;color:#702118;max-width:100%;overflow-wrap:anywhere}.card.hero .note{background:#fffaf0;color:#19262a}.card.hero .note button.link,.card.hero .note a{color:#702118}

/* ===== お守りテーマ：絵と金額面の色だけを切り替える（土台は宝船 E2） ===== */
html[data-art="E4"] .card.hero{background:#16453e}html[data-art="E4"] .card.hero::before{background-image:url("data:image/webp;base64,")}
