/* ===== 絵のえらび（設定）：絵を見て選ぶ ===== */
.art-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:6px}.art-pick{display:block;padding:0;margin:0;background:var(--panel);border:2px solid var(--line);border-radius:var(--r);text-align:left;font:inherit;color:var(--ink);cursor:pointer;overflow:hidden;min-height:44px}.art-pick .art-pic{display:block;width:100%;aspect-ratio:2/1;background-size:cover;background-position:center;background-color:var(--soft)}.art-pick .art-name{display:block;padding:6px 8px;font-size:14px;line-height:1.3;font-weight:600}.art-pick .art-mean{display:block;padding:0 8px 8px;font-size:13px;line-height:1.35;color:var(--ink);font-weight:400}.art-pick.on{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent)}.art-pick:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.art-pick[data-art="E2"] .art-pic{background-image:url("data:image/jpeg;base64,")}
.art-pick[data-art="E4"] .art-pic{background-image:url("data:image/jpeg;base64,")}
